package app.kivo.store;
import android.content.*;import android.content.pm.*;import android.graphics.*;import android.graphics.drawable.Drawable;import android.webkit.WebResourceResponse;import org.json.*;import java.util.*;import java.io.*;
/** Device inventory stays local. Only exact package matches are offered as update sources. */
final class InstalledApps {
 final java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();final MainActivity host;volatile JSONArray snapshot=new JSONArray();volatile boolean checking;final Set<String> inspected=java.util.concurrent.ConcurrentHashMap.newKeySet();
 InstalledApps(MainActivity h){host=h;rescan=()->{if(!worker.isShutdown())worker.execute(()->scan());};}
 boolean installed(String pkg){if(!validPackage(pkg))return false;try{host.getPackageManager().getPackageInfo(pkg,0);return true;}catch(Exception e){return false;}}
 static boolean validPackage(String pkg){return pkg!=null&&pkg.matches("[A-Za-z0-9_]+(?:\\.[A-Za-z0-9_]+)+");}
 final android.os.Handler changes=new android.os.Handler(android.os.Looper.getMainLooper());
 final Runnable rescan;
 void inspect(String repo){JSONObject a=host.catalog.get(repo);JSONObject metadata=host.sourceEntry(repo);String pkg=a==null?"":a.optString("package");if(!validPackage(pkg)&&metadata!=null)pkg=metadata.optString("package");if(!validPackage(pkg))pkg=host.prefs.getString("pkg:"+repo,"");if(validPackage(pkg)){if(inspected.size()>200)inspected.clear();inspected.add(pkg);}requestScan();}
 void requestScan(){changes.removeCallbacks(rescan);changes.postDelayed(rescan,200);}
 void close(){changes.removeCallbacks(rescan);worker.shutdown();}
 void inventoryState(boolean scanning,String error,boolean partial,int count){JSONObject state=new JSONObject();try{state.put("scanning",scanning).put("error",error).put("partial",partial).put("count",count).put("checked",System.currentTimeMillis());host.send("inventoryState",state);}catch(Exception ignored){}}
 String label(PackageManager pm,PackageInfo info){try{CharSequence text=pm.getApplicationLabel(info.applicationInfo);if(text!=null&&!text.toString().trim().isEmpty())return text.toString();}catch(Exception ignored){}return info.packageName;}
 JSONObject basic(PackageManager pm,PackageInfo info)throws Exception{return new JSONObject().put("package",info.packageName).put("name",label(pm,info)).put("installedVersion",info.versionName==null?"":info.versionName).put("installedCode",MainActivity.code(info)).put("installed",true).put("system",info.applicationInfo!=null&&(info.applicationInfo.flags&ApplicationInfo.FLAG_SYSTEM)!=0).put("repo","").put("sourceMatched",false).put("updateAvailable",false);}
 synchronized void scan(){inventoryState(true,"",false,0);try{
  Map<String,List<JSONObject>> byPackage=new HashMap<>();List<JSONObject> sources=new ArrayList<>(host.fdroid.entries.values());sources.addAll(host.directory.values());sources.addAll(host.catalog.values());
  for(JSONObject a:sources)try{if(a==null)continue;String pkg=a.optString("package");if(pkg.isEmpty())pkg=host.prefs.getString("pkg:"+a.optString("repo"),"");if(pkg.isEmpty()){JSONObject metadata=host.sourceEntry(a.optString("repo"));if(metadata!=null)pkg=metadata.optString("package");}if(validPackage(pkg))byPackage.computeIfAbsent(pkg,k->new ArrayList<>()).add(a);}catch(Exception ignored){}
  Map<String,JSONObject> tracks=new HashMap<>();try{JSONArray saved=new JSONArray(host.prefs.getString("tracked","[]"));for(int i=0;i<saved.length();i++){JSONObject track=saved.optJSONObject(i);if(track!=null&&validPackage(track.optString("package")))tracks.put(track.optString("package"),track);}}catch(Exception ignored){}
  Set<String> known=new HashSet<>(tracks.keySet());known.addAll(inspected);for(Map.Entry<String,?> item:host.prefs.getAll().entrySet())if(item.getKey().startsWith("pkg:")&&item.getValue() instanceof String&&validPackage((String)item.getValue()))known.add((String)item.getValue());
  final PackageManager pm=host.getPackageManager();InstalledPackages<PackageInfo> collector=new InstalledPackages<>(new InstalledPackages.Backend<PackageInfo>(){
   public List<PackageInfo> all(){return pm.getInstalledPackages(0);}
   public List<String> launchers(){List<String> names=new ArrayList<>();Intent intent=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER);for(ResolveInfo item:pm.queryIntentActivities(intent,0))if(item.activityInfo!=null)names.add(item.activityInfo.packageName);return names;}
   public PackageInfo lookup(String pkg)throws Exception{return pm.getPackageInfo(pkg,0);}
   public String id(PackageInfo info){return info==null?"":info.packageName;}
  });InstalledPackages.Result<PackageInfo> discovered=collector.collect(known);List<JSONObject> out=new ArrayList<>();int omitted=0;
  int flags=android.os.Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;
  for(PackageInfo info:discovered.packages.values()){if(info==null||info.packageName.equals(host.getPackageName())||info.applicationInfo==null)continue;JSONObject row;try{row=basic(pm,info);}catch(Exception e){omitted++;continue;}try{
   JSONObject track=tracks.get(info.packageName),best=null;int bestScore=-1;String installedSign="";List<JSONObject> matches=byPackage.getOrDefault(info.packageName,Collections.emptyList());boolean needSigner=track!=null;for(JSONObject a:matches)if("fdroid".equals(a.optString("source")))needSigner=true;if(needSigner)try{installedSign=host.signers(pm.getPackageInfo(info.packageName,flags));}catch(Exception ignored){}
   for(JSONObject a:matches){boolean fdroid="fdroid".equals(a.optString("source")),same=fdroid&&sameSigner(a,installedSign);int score=(!a.optBoolean("indexed")&&a.optBoolean("available")?25:0)+(track!=null&&track.optString("repo").equals(a.optString("repo"))?100:0)+(same?70:fdroid?0:a.optBoolean("available")?40:20);if(score>bestScore){best=a;bestScore=score;}}
   row.put("launchable",discovered.launchable.contains(info.packageName));row.put("repo",best!=null?best.optString("repo"):track==null?"":track.optString("repo"));row.put("source",best==null?"":best.optString("source","github"));row.put("latestVersion",best==null?"":best.optString("version"));row.put("sourceMatched",best!=null);row.put("pending",best!=null&&best.optBoolean("indexed"));
   boolean newer=best!=null&&UpdatePolicy.newer(best.optString("source"),best.optLong("versionCode"),best.optString("version"),MainActivity.code(info),info.versionName);boolean signerUnknown=best!=null&&"fdroid".equals(best.optString("source"))&&installedSign.isEmpty();boolean signerConflict=best!=null&&"fdroid".equals(best.optString("source"))&&!signerUnknown&&!sameSigner(best,installedSign);boolean ready=newer&&!signerConflict&&!signerUnknown&&!best.optBoolean("indexed")&&best.optBoolean("available")&&host.bestAsset(best.optJSONArray("assets"))>0;
   row.put("newerFound",newer);row.put("signerUnknown",signerUnknown);row.put("signerConflict",signerConflict);row.put("updateAvailable",ready);row.put("assetId",ready?host.bestAsset(best.optJSONArray("assets")):-1);row.put("versionCheckedAt",best==null?0:best.optLong("checked"));row.put("fileReady",track!=null&&new File(host.getFilesDir(),"apks/"+track.optString("file")).isFile());if(track!=null){row.put("downloadedVersion",track.optString("downloadedVersion"));row.put("downloadedCode",track.optLong("downloadedCode"));row.put("savedApkInstalled",DownloadInstallPolicy.installed(track.optLong("downloadedCode"),MainActivity.code(info),host.prefs.getString("sign:"+track.optString("repo"),""),installedSign));}
  }catch(Exception e){row.put("metadataError",true);}out.add(row);}
  Set<String> packages=new HashSet<>();for(JSONObject row:out)packages.add(row.optString("package"));int count=out.size();for(JSONObject track:tracks.values())if(!packages.contains(track.optString("package")))try{JSONObject copy=new JSONObject(track.toString());copy.put("name",track.optString("package"));copy.put("installed",false);copy.put("updateAvailable",false);copy.put("fileReady",new File(host.getFilesDir(),"apks/"+copy.optString("file")).isFile());out.add(copy);}catch(Exception ignored){}
  Collections.sort(out,(a,b)->{int update=Boolean.compare(b.optBoolean("updateAvailable"),a.optBoolean("updateAvailable"));if(update!=0)return update;int system=Boolean.compare(a.optBoolean("system")&&!a.optBoolean("launchable"),b.optBoolean("system")&&!b.optBoolean("launchable"));return system!=0?system:a.optString("name").compareToIgnoreCase(b.optString("name"));});JSONArray result=new JSONArray();for(JSONObject row:out)result.put(row);snapshot=result;host.send("installed",result);inventoryState(false,count==0?"Android no devolvió aplicaciones visibles. Pulsa Volver a detectar.":"",discovered.sourceFailures>0||omitted>0,count);
 }catch(Exception e){inventoryState(false,"No se pudo completar la lectura. Pulsa Volver a detectar.",true,snapshot.length());}}
 static boolean sameSigner(JSONObject app,String expected){if(expected.isEmpty())return false;JSONArray assets=app.optJSONArray("assets");if(assets==null)return false;for(int i=0;i<assets.length();i++){JSONObject asset=assets.optJSONObject(i);if(asset==null)continue;JSONArray sign=asset.optJSONArray("signers");if(sign==null)continue;List<String> parts=new ArrayList<>();for(int j=0;j<sign.length();j++)parts.add(sign.optString(j));Collections.sort(parts);if(expected.equals(String.join(",",parts)))return true;}return false;}
 void chooseInstalled(String raw){final String repo;try{repo=MainActivity.repo(raw);}catch(Exception e){return;}worker.execute(()->{scan();List<String> labels=new ArrayList<>();Map<String,String> packages=new HashMap<>();for(int i=0;i<snapshot.length();i++){JSONObject row=snapshot.optJSONObject(i);if(row==null||!row.optBoolean("installed")||row.optBoolean("system")&&!row.optBoolean("launchable"))continue;String label=row.optString("name")+" · "+row.optString("package");labels.add(label);packages.put(label,row.optString("package"));}host.runOnUiThread(()->{if(host.isFinishing()||host.isDestroyed())return;android.widget.EditText search=new android.widget.EditText(host);search.setSingleLine(true);search.setHint("Buscar una app instalada");android.widget.LinearLayout header=new android.widget.LinearLayout(host);header.setOrientation(1);header.setPadding(24,16,24,8);android.widget.TextView title=new android.widget.TextView(host);title.setText("¿Cuál ya tienes instalada?");title.setTextSize(20);header.addView(title);header.addView(search);android.widget.ArrayAdapter<String> adapter=new android.widget.ArrayAdapter<>(host,android.R.layout.simple_list_item_1,labels);search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){adapter.getFilter().filter(s);}public void afterTextChanged(android.text.Editable e){}});new android.app.AlertDialog.Builder(host).setCustomTitle(header).setAdapter(adapter,(dialog,which)->{String pkg=packages.get(adapter.getItem(which));if(!validPackage(pkg)||!installed(pkg)){host.status("La app ya no está instalada. Vuelve a detectar.");return;}new android.app.AlertDialog.Builder(host).setTitle("Vincular esta instalación").setMessage("Vincula "+pkg+" con "+repo+" solo si corresponde a esta ficha. Kivo comprobará el paquete y la firma del APK antes de instalar cualquier actualización.").setPositiveButton("Vincular",(d,w)->{host.prefs.edit().putString("pkg:"+repo,pkg).apply();JSONObject current=host.catalog.get(repo);if(current!=null)try{JSONObject copy=new JSONObject(current.toString()).put("package",pkg);host.catalog.put(repo,copy);}catch(Exception ignored){}JSONObject metadata=host.directory.get(repo.toLowerCase(java.util.Locale.ROOT));if(metadata!=null)try{host.directory.put(repo.toLowerCase(java.util.Locale.ROOT),new JSONObject(metadata.toString()).put("package",pkg));host.saveCandidates();host.publishDirectory();}catch(Exception ignored){}host.sendVerified();host.publish();inspect(repo);host.status("Instalación vinculada. Ya puedes abrirla desde Kivo.");}).setNegativeButton("Cancelar",null).show();}).setNegativeButton("Cancelar",null).show();});});}
 void refresh(){if(checking)return;checking=true;host.send("updateChecking",true);host.searches.execute(()->{int checked=0,pending=0;try{scan();Set<String> repos=new LinkedHashSet<>();for(int i=0;i<snapshot.length();i++){JSONObject row=snapshot.getJSONObject(i);String repo=row.optString("repo");if(row.optBoolean("installed")&&row.optBoolean("sourceMatched")&&!repo.startsWith("fdroid/"))repos.add(repo);}List<String> order=new ArrayList<>(repos);Collections.sort(order,(a,b)->Long.compare(host.prefs.getLong("installedCheck:"+a,0),host.prefs.getLong("installedCheck:"+b,0)));for(String repo:order){if(System.currentTimeMillis()-host.prefs.getLong("installedCheck:"+repo,0)<30*60000)continue;if(checked>=8){pending++;continue;}host.sync(repo);host.prefs.edit().putLong("installedCheck:"+repo,System.currentTimeMillis()).apply();checked++;}host.publish();host.status("Catálogo F-Droid guardado comparado y "+checked+" proyectos GitHub consultados."+(pending>0?" Quedan "+pending+" proyectos; pulsa comprobar otra vez.":""));}catch(Exception e){host.status(e.getMessage());}finally{scan();checking=false;host.send("updateChecking",false);}});}
 void download(String pkg){host.transfers.execute(()->{scan();try{for(int i=0;i<snapshot.length();i++){JSONObject row=snapshot.getJSONObject(i);if(row.optString("package").equals(pkg)&&row.optBoolean("updateAvailable")){host.downloads.enqueue(row.getString("repo"),row.getLong("assetId"));return;}}throw new IOException("No hay una actualización compatible comprobada en el catálogo. Actualiza las fuentes y vuelve a comprobar.");}catch(Exception e){host.status(e.getMessage());}});}
 WebResourceResponse icon(String pkg){try{if(!validPackage(pkg))return host.missingImage();Drawable d=host.getPackageManager().getApplicationIcon(pkg);Bitmap b=Bitmap.createBitmap(128,128,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);d.setBounds(0,0,128,128);d.draw(c);ByteArrayOutputStream out=new ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.PNG,100,out);b.recycle();return new WebResourceResponse("image/png",null,new ByteArrayInputStream(out.toByteArray()));}catch(Exception e){return host.missingImage();}}
}
